        /// <summary>The fit for a body type, falling back through its name's suffixes ("F_010_Chubby_Ratkin" to "F_010_Chubby").</summary>
        public static Fit For(string bodyTypeDefName)
        {
            string name = bodyTypeDefName;
            while (!string.IsNullOrEmpty(name))
            {
                if (byBodyType.TryGetValue(name, out Fit fit))
                    return fit;
                int cut = name.LastIndexOf('_');
                if (cut <= 0)
                    break;
                name = name.Substring(0, cut);
            }
            return Fallback;
        }
